from __future__ import annotations
from .canonical import with_digest
def build_handoff(run: dict,decision: dict,assessment: dict,security: dict,events: dict,provenance: dict) -> dict:
    body={'schema_version':'1.0.0','handoff_type':'ACL11_TO_ACL12','runtime_custody_run_id':run['runtime_custody_run_id'],'promotion_run_id':run['promotion_run_id'],'runtime_candidate_count':run['runtime_candidate_count'],'custody_decision':decision['decision'],'custody_decision_digest':decision['custody_decision_digest'],'parity_assessment_digest':assessment['assessment_digest'],'security_report_digest':security['security_report_digest'],'event_ledger_digest':events['ledger_digest'],'provenance_graph_digest':provenance['graph_digest'],'required_acl12_actions':['VERIFY_RUNTIME_CUSTODY_PACKAGE','HARDEN_SECURITY_BOUNDARIES','ISSUE_SECURITY_READINESS_DECISION'],'forbidden_acl12_actions':['INVENT_RUNTIME_CANDIDATE','BYPASS_PARITY_OR_SIGNING_GATES','ACCESS_PRODUCTION_KEYS_IN_REFERENCE_MODE','AUTHORIZE_LIVE_ORDER','ACTIVATE_CAPITAL'],'runtime_generation_allowed':False,'runtime_activation_allowed':False,'live_order_submission_allowed':False,'capital_activation_allowed':False}
    return with_digest(body,'handoff_digest')
